def _normalize_platform(platform: str) -> str:
    """Normalize a platform name for comparison.

    Replaces ``.``, ``-``, and whitespace with ``_``, then lowercases.
    This matches the normalization used by :mod:`packaging.tags`.
    """
    return platform.replace("_", "-").replace(".", "-").replace(" ", "-").lower().replace("-", "_")
